import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { ChevronRight as NextIcon, ChevronLeft as PrevIcon } from "@exp-textura/icons";
import { Button } from "@components/button";
import { IconButton } from "@components/icon-button";

import {
  type PaginationProps,
  type PaginationItemsProps,
  type PaginationPrevProps,
  type PaginationNextProps,
  type PaginationEllipsisProps,
  PageItem,
  PaginationAriaLabels,
} from "./pagination.types";
import { PaginationClasses, StyledPagination } from "./pagination.styles";
import { usePagination, PaginationContext, usePaginationContext } from "./hooks/use-pagination";
const defaultGetItemAriaLabel = (
  label: PaginationAriaLabels,
  page?: number,
): string | undefined => {
  switch (label) {
    case PaginationAriaLabels.PageIndexButton:
      return `Go to page ${page}`;
  }
};
const PaginationRoot = forwardRef<HTMLDivElement, PaginationProps>(
  (
    {
      start = 1,
      finish = 1,
      spread = 7,
      selected = 1,
      onSelectedChange,
      className,
      variant = "default",
      children,
      "aria-label": ariaLabel,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const { items, selectedIndex, selectIndex } = usePagination(
      start,
      finish,
      spread,
      selected,
      onSelectedChange,
    );

    const contextValue = {
      items,
      selectedIndex,
      selectIndex,
      start,
      finish,
      spread,
    };

    return (
      <PaginationContext.Provider value={contextValue}>
        <StyledPagination
          ref={ref}
          aria-label={ariaLabel || "Pagination"}
          className={clsx(PaginationClasses.root, className)}
          currentTheme={theme}
          finish={finish}
          role="navigation"
          spread={spread}
          start={start}
          variant={variant}
          {...props}
        >
          {children}
        </StyledPagination>
      </PaginationContext.Provider>
    );
  },
);
PaginationRoot.displayName = "Pagination";

const PaginationPrev: React.FC<PaginationPrevProps> = ({
  className,
  children,
  "aria-label": ariaLabel,
}) => {
  const { selectedIndex, selectIndex, start } = usePaginationContext();

  const buttonProps = {
    "aria-label": ariaLabel || "Go to previous page",
    className: clsx(PaginationClasses.prevButton, className),
    "data-key": "prevBtn",
    disabled: selectedIndex === start,
    onClick: () => selectIndex(selectedIndex - 1),
  };

  if (React.isValidElement(children)) {
    return React.cloneElement(children, buttonProps);
  }

  return (
    <IconButton buttonType="secondary" size="sm" {...buttonProps}>
      <PrevIcon />
    </IconButton>
  );
};
PaginationPrev.displayName = "Pagination.Prev";

const PaginationNext: React.FC<PaginationNextProps> = ({
  className,
  children,
  "aria-label": ariaLabel,
}) => {
  const { selectedIndex, selectIndex, finish } = usePaginationContext();

  const buttonProps = {
    "aria-label": ariaLabel || "Go to next page",
    className: clsx(PaginationClasses.nextButton, className),
    "data-key": "nextBtn",
    disabled: selectedIndex === finish,
    onClick: () => selectIndex(selectedIndex + 1),
  };

  if (React.isValidElement(children)) {
    return React.cloneElement(children, buttonProps);
  }

  return (
    <IconButton buttonType="secondary" size="sm" {...buttonProps}>
      <NextIcon />
    </IconButton>
  );
};
PaginationNext.displayName = "Pagination.Next";

const PaginationEllipsis: React.FC<PaginationEllipsisProps> = ({ className }) => (
  <Button
    className={clsx(PaginationClasses.ellipsis, className)}
    data-key="ellipsisBtn"
    disabled={true}
  >
    ...
  </Button>
);
PaginationEllipsis.displayName = "Pagination.Ellipsis";

const PaginationItems: React.FC<PaginationItemsProps> = ({
  getItemAriaLabel = defaultGetItemAriaLabel,
  render,
}) => {
  const { items, selectedIndex, selectIndex } = usePaginationContext();
  const pageButtonProps = (item: PageItem) => ({
    "aria-label": getItemAriaLabel(PaginationAriaLabels.PageIndexButton, item.value),
    "data-key": "pageBtn",
    selected: item.value === selectedIndex,
    "data-selected": item.value === selectedIndex ? true : undefined,
    onClick: () => item.value && selectIndex(item.value),
  });
  const ellipsisButtonProps = {
    disabled: true,
  };

  return (
    <>
      {items.map((item, i) => {
        const ariaCurrent = item.value === selectedIndex ? "page" : undefined;
        if (render) {
          const rendered = render(item, i);
          if (React.isValidElement(rendered)) {
            return React.cloneElement(
              rendered as React.ReactElement,
              item.type === "page"
                ? {
                    ...pageButtonProps(item),
                    ["aria-current"]: ariaCurrent,
                    className: clsx(PaginationClasses.pageButton, rendered.props.className),
                  }
                : {
                    ...ellipsisButtonProps,
                    className: clsx(PaginationClasses.ellipsis, rendered.props.className),
                  },
            );
          } else {
            throw new Error("Pagination.Items render prop must return a valid React element");
          }
        }

        return item.type === "page" ? (
          <Button
            key={i}
            aria-current={ariaCurrent}
            buttonType="tertiary"
            className={PaginationClasses.pageButton}
            {...pageButtonProps(item)}
          >
            {item.value}
          </Button>
        ) : (
          <Pagination.Ellipsis key={i} />
        );
      })}
    </>
  );
};
PaginationItems.displayName = "Pagination.Items";

type PaginationCompoundComponent = typeof PaginationRoot & {
  Prev: typeof PaginationPrev;
  Ellipsis: typeof PaginationEllipsis;
  Items: typeof PaginationItems;
  Next: typeof PaginationNext;
};

const Pagination = PaginationRoot as PaginationCompoundComponent;

Pagination.Prev = PaginationPrev;
Pagination.Ellipsis = PaginationEllipsis;
Pagination.Items = PaginationItems;
Pagination.Next = PaginationNext;

export default Pagination;
